-- M4 seed for The BOLT — GENERATED by tools/m4-seed.mjs. Do not hand-edit.
-- Regenerate after any change to m4-format.mjs or clock-order.mjs.
--
-- 11 clocks over 2 rotation weeks
-- (336 grid cells). Golden Hour alternates A/B variants by
-- (week + dow) % 2, which is why the cycle is 2 weeks rather than 1.
--
-- PREREQUISITE: run sync-library first. song_categories derives from
-- songs.rdj_subcategory_id; the mirror is a derived cache, never a source of truth.

BEGIN;

-- Teardown. Logs are dropped because their log_items reference clock_positions;
-- a seed that left them would orphan every approved log against clocks that no
-- longer exist.
DELETE FROM log_items WHERE log_id IN (SELECT id FROM logs WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3');
DELETE FROM logs WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3';
DELETE FROM format_grid WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3';
DELETE FROM clock_positions WHERE clock_id IN (SELECT id FROM clocks WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3');
DELETE FROM clocks WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3';
DELETE FROM rules WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3';
DELETE FROM song_categories WHERE category_id IN (SELECT id FROM categories WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3');
DELETE FROM categories WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3';

-- Rotation: the grid repeats over 2 weeks. The epoch anchors week 0 and must
-- never move — changing it flips which variant every Golden Hour cell resolves to.
UPDATE stations SET format_cycle_weeks = 2, format_cycle_epoch = '2026-08-03'::timestamp
  WHERE id = '6a42a599-acfc-404f-a524-9fb9b65d36f3';

-- Parent music categories

-- Child music categories. default_target_turnover_hours is the SOLVED turnover from
-- tools/depth-solver.mjs, not an aspiration: depth was chosen to land these.

-- F is the late-stage fallback: it exists so that an hour-length miscalculation or a
-- pool that cannot fill has something legal to take rather than leaving dead air. It
-- is never called by a clock position and costs nothing to carry.

-- Imaging categories. Per-block TOH IDs (subcats 40-48) so the hour opens with what
-- the station IS at that moment rather than one generic ID everywhere.

-- Library <-> clockset contract. Identity is the RadioDJ subcategory ID; the mirror
-- follows RadioDJ (ADR-0001 §3.2 stage 1). B is subcat 1 alone since the 2026-08-02
-- consolidation retired subcat 5.
SELECT s.id, c.id FROM songs s JOIN categories c ON c.station_id = s.station_id
WHERE s.station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND (
  (c.name = 'A1' AND s.rdj_subcategory_id = 4) OR
  (c.name = 'A2' AND s.rdj_subcategory_id = 2) OR
  (c.name = 'B' AND s.rdj_subcategory_id = 1) OR
  (c.name = 'C' AND s.rdj_subcategory_id = 3) OR
  (c.name = 'N' AND s.rdj_subcategory_id = 23) OR
  (c.name = 'R1' AND s.rdj_subcategory_id = 24) OR
  (c.name = 'R2' AND s.rdj_subcategory_id = 25) OR
  (c.name = 'R3' AND s.rdj_subcategory_id = 26) OR
  (c.name = 'G2010' AND s.rdj_subcategory_id = 29) OR
  (c.name = 'G2000' AND s.rdj_subcategory_id = 28) OR
  (c.name = 'G1990' AND s.rdj_subcategory_id = 27) OR
  (c.name = 'H1' AND s.rdj_subcategory_id = 30) OR
  (c.name = 'H2' AND s.rdj_subcategory_id = 49) OR
  (c.name = 'Discovery' AND s.rdj_subcategory_id = 6) OR
  (c.name = 'F' AND s.rdj_subcategory_id = 31) OR
  (c.name = 'GDEEP' AND s.rdj_subcategory_id = 37) OR
  (c.name = 'TOH ES' AND s.rdj_subcategory_id = 40) OR
  (c.name = 'TOH FF' AND s.rdj_subcategory_id = 41) OR
  (c.name = 'TOH HD' AND s.rdj_subcategory_id = 42) OR
  (c.name = 'TOH CO' AND s.rdj_subcategory_id = 43) OR
  (c.name = 'TOH WW' AND s.rdj_subcategory_id = 44) OR
  (c.name = 'TOH WD' AND s.rdj_subcategory_id = 45) OR
  (c.name = 'TOH GH' AND s.rdj_subcategory_id = 46) OR
  (c.name = 'TOH EM' AND s.rdj_subcategory_id = 47) OR
  (c.name = 'TOH DN' AND s.rdj_subcategory_id = 48) OR
  (c.name = 'Liners' AND s.rdj_subcategory_id = 9) OR
  (c.name = 'New-Music Sweepers' AND s.rdj_subcategory_id = 33) OR
  (c.name = 'Gold Backsells' AND s.rdj_subcategory_id = 34) OR
  (c.name = 'Relaunch Sweepers' AND s.rdj_subcategory_id = 8) OR
  (c.name = 'Station Promos' AND s.rdj_subcategory_id = 12) OR
  (c.name = 'Heritage Backsells' AND s.rdj_subcategory_id = 35)
)
ON CONFLICT ON CONSTRAINT song_categories_song_category_unique DO NOTHING;

-- One clock per block. GHa/GHb and DNa/DNb are variants of one identity (see
-- IDENTITY in m4-format.mjs) and share a TOH pool, but are separate clocks because
-- their position order differs.

-- Clock positions. Music is placed by two-level proportional spread (tier first, then
-- category within tier); imaging is woven in contextually — a New-Music sweeper ahead
-- of a new track, a Gold Backsell behind a gold one. Emitted from clockSequence() so
-- this matches tools/clock-order.mjs exactly.
--
-- constraints.fallbackCategoryId is the governing fallback policy: currents never
-- fall back to gold. Unplanned fallback is still programming — under M3, G2010 carried
-- 651 fallback slots on top of its own 368, and the station's gold-heavy sound was a
-- symptom of shallow currents rather than a design choice.

-- Format grid: 336 cells (2 weeks x 168 hours), station-local.
-- Golden Hour resolves to GHa or GHb by (week + dow) % 2, so a listener in a fixed
-- weekly slot gets the other variant next week.

-- Rules. Vertical separation (artist/title) keeps unlike things apart within an hour;
-- horizontal separation keeps a song off the same TIME OF DAY on successive plays.
--
-- Horizontal is scoped to currents and R1 ONLY. Applied uniformly it made things
-- worse — R1 lost 19pp and Discovery yielded on 93% of slots, and a yield drops album
-- separation and tempo clash with it. Params are yield-capped at <=25%.

-- Assert the seed landed. A silent partial seed is far worse than a failed one: the
-- station would generate logs against a half-built clockset and nobody would know
-- until air. Each check aborts the transaction rather than warning.
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM clocks WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3';
  IF n <> 11 THEN RAISE EXCEPTION 'expected 11 clocks, got %', n; END IF;
  SELECT count(*) INTO n FROM format_grid WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3';
  IF n <> 336 THEN RAISE EXCEPTION 'expected 336 grid cells, got %', n; END IF;
  SELECT count(*) INTO n FROM clock_positions cp JOIN clocks c ON c.id = cp.clock_id
    WHERE c.station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3';
  IF n <> 234 THEN RAISE EXCEPTION 'expected 234 clock positions, got %', n; END IF;
  -- Every position must resolve a category. A NULL here is a category name in the
  -- generator that does not exist in the categories table — the M2-era failure where
  -- subcategory 34 sat unmapped and nobody noticed.
  SELECT count(*) INTO n FROM clock_positions cp JOIN clocks c ON c.id = cp.clock_id
    WHERE c.station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND cp.category_id IS NULL;
  IF n > 0 THEN RAISE EXCEPTION '% clock positions have no category', n; END IF;
  -- Every music category a clock calls must actually have songs mapped to it.
  SELECT count(*) INTO n FROM categories cat WHERE cat.station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3'
    AND cat.kind = 'music' AND cat.parent_id IS NOT NULL
    AND NOT EXISTS (SELECT 1 FROM song_categories sc WHERE sc.category_id = cat.id);
  IF n > 0 THEN RAISE EXCEPTION '% music categories have no songs — re-sync the library first', n; END IF;
END $$;

COMMIT;
